/** One actual asynchronous captured Rack harvest, retaining its internal physical modules. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeRackHarvestChecks {
    private static final BlockPos ROOT=new BlockPos(15,110,15),SOURCE=ROOT.east(2);private static ServerLevel world;private static Actor actor;private static int stage,ticks,checks;private static boolean running,fired;private static java.util.concurrent.CompletableFuture<Void> partial;private static final java.util.concurrent.atomic.AtomicBoolean pause=new java.util.concurrent.atomic.AtomicBoolean();
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211578),"NativeRackHarvest"));}}
    private static String phase(){return System.getProperty("vandorlabs.rackHarvestPhase","normal");}
    private static boolean enabled(){return Boolean.getBoolean("vandorlabs.rackHarvestChecks");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Rack harvest stage="+stage+" ticks="+ticks+": "+why);}
    private static NativeGearEntity root(){var owner=NativeGearFormation.at(world,ROOT);need(owner!=null&&!owner.inert(),"healthy arm root");return owner;}
    private static List<net.minecraft.world.entity.item.ItemEntity> drops(){return world.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(ROOT).inflate(12));}
    private static boolean aim(){for(var box:root().payload().boxes(root(),root().progress()))for(var side:Direction.values()){var target=box.getCenter();var eye=target.add(Vec3.atLowerCornerOf(side.getNormal()).scale(3.5));var look=target.subtract(eye).normalize();actor.setPos(eye.x,eye.y-actor.getEyeHeight(),eye.z);actor.setYRot((float)Math.toDegrees(Math.atan2(-look.x,look.z)));actor.setXRot((float)-Math.toDegrees(Math.asin(look.y)));var hit=NativeGearHarvest.target(actor);if(hit!=null&&hit.owner()==root())return true;}return false;}
    private static int modules(){if(!(world.getBlockEntity(SOURCE) instanceof NativeRackEntity rack)||rack.inert())return 0;var copies=rack.ownedModuleDrops();var markers=new HashSet<Integer>();for(var item:copies)markers.add(NativeRackData.data(item).getInt("RackHarvestMarker"));need(copies.size()==3&&markers.equals(Set.of(17,18,19)),"native source retains exact three original private modules");return copies.size();}
    private static void fault(String where){if(!phase().equals("crash")||!where.equals("after-cell")||fired)return;need(!new net.minecraft.world.level.ChunkPos(ROOT).equals(new net.minecraft.world.level.ChunkPos(SOURCE)),"source save genuinely excludes root chunk");need(world.getBlockState(SOURCE).isAir()&&root().payload()!=null&&!root().payload().materialized()&&drops().isEmpty(),"durable ARMED capture holds sole modules without native source/drop copies");fired=true;pause.set(true);var pos=new net.minecraft.world.level.ChunkPos(SOURCE);var chunk=world.getChunkSource().getChunkNow(pos.x,pos.z);need(chunk!=null,"loaded source checkpoint chunk");partial=world.getChunkSource().chunkMap.write(pos,net.minecraft.world.level.chunk.storage.ChunkSerializer.write(world,chunk)).thenCompose(ignored->((com.vandorlabs.neoforge.mixin.NativeRampChunkStorageAccess)(Object)world.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true)).thenRun(()->{System.out.println("[vandorlabs][rack-harvest] crash PASS checks="+checks+" realAsyncDurableARMED/afterSourceCell/sourceOnlyCrossChunkSave/zeroLooseModules/abruptHalt");System.out.flush();Runtime.getRuntime().halt(0);});}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{world=event.getServer().overworld();need(System.getProperty("vandorlabs.gearJournalPhase","").equals("rack-capture"),"explicit private journal fault gate enabled");for(var facing:Direction.values())for(var side:Direction.values())need(NativeRackBindings.BLOCK.defaultBlockState().setValue(NativeRackBlock.FACING,facing).isFaceSturdy(world,SOURCE,side)==com.vandorlabs.rack.ModuleRackGeometry.hasClosedBoundary(facing.get3DDataValue(),side.get3DDataValue()),"shared closed-shell/open-front support policy "+facing+"/"+side);var settingsProbe=new CompoundTag();NativeRackData.transmission(settingsProbe,new NativeRackData.Transmission(com.vandorlabs.redstone.ChannelList.of(17),32,false,true));settingsProbe.getCompound("ForgeData").putString("OpaqueNeighborSetting","preserved");NativeRackData.transmission(settingsProbe,NativeRackData.Transmission.fresh());need(NativeRackData.transmission(settingsProbe).equals(NativeRackData.Transmission.fresh()),"default transmission reset removes old saved main bank");need(settingsProbe.getCompound("ForgeData").getString("OpaqueNeighborSetting").equals("preserved"),"default transmission reset preserves opaque siblings");actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);for(int x=-1;x<=2;x++)for(int z=-1;z<=2;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}if(phase().equals("recover")){need(root().blocked()&&root().progress()==1&&root().payload()==null,"cold ARMED rollback restored last native endpoint before gameplay");need(modules()==3&&drops().isEmpty(),"cold rollback has exactly one usable native Rack3 and no loose module duplicates");root().authorize(actor);need(root().command(false),"recovered native Rack can retry the same capture");stage=1;running=true;return;}for(int x=9;x<=23;x++)for(int y=104;y<=116;y++)for(int z=9;z<=23;z++)world.setBlock(new BlockPos(x,y,z),y==104?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),18);world.setBlock(ROOT.west(),Blocks.STONE.defaultBlockState(),3);actor.setPos(12,111,12);actor.setYRot(0);var stack=new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.ROTATING.id),2);var choices=NativeGearSettings.defaults().choices();choices.putBoolean("RotatePayload",false);var data=new CompoundTag();data.put(NativeGearItem.SETTINGS,choices);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);for(int part=0;part<2;part++){var support=ROOT.relative(Direction.EAST,part-1);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(.5,0,0),Direction.EAST,support,false)).consumesAction(),"ordinary supported Survival arm placement");}need(stack.isEmpty(),"two section items consumed");NativeGearJournal.testPause=pause::get;running=true;}catch(Throwable failure){fail(failure);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<800,"bounded async harvest progress="+root().progress()+" busy="+NativeGearJournal.busy(root())+" error="+root().error());if(ticks%100==0)System.out.println("[vandorlabs][rack-harvest] progress stage="+stage+" tick="+ticks+" phase="+root().progress()+" busy="+NativeGearJournal.busy(root()));
        if(stage==0){if(!root().controller()||root().assembly().columnHeight()!=2)return;world.setBlock(SOURCE,NativeRackBindings.BLOCK.defaultBlockState(),3);var rack=(NativeRackEntity)world.getBlockEntity(SOURCE);for(int slot=0;slot<3;slot++){var module=new ItemStack(slot==2?NativeRackBindings.AUTOPILOT:NativeRackBindings.BLANK);var privateData=new CompoundTag();privateData.putInt("RackHarvestMarker",slot+17);module.set(DataComponents.CUSTOM_DATA,CustomData.of(privateData));need(rack.insert(slot,module,false)&&module.isEmpty(),"three physical modules installed once");}var building=new ItemStack(Blocks.STONE);actor.setItemInHand(InteractionHand.MAIN_HAND,building);need(actor.gameMode.useItemOn(actor,world,building,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(SOURCE).add(0,0,-.5),Direction.NORTH,SOURCE,false)).consumesAction()&&building.isEmpty()&&world.getBlockState(SOURCE.north()).is(Blocks.STONE)&&rack.ownedModuleDrops().size()==3,"ordinary building item places beside Rack without opening dialog or extracting a module");world.setBlock(SOURCE.north(),Blocks.AIR.defaultBlockState(),18);root().authorize(actor);world.getServer().saveEverything(true,true,true);NativeGearJournal.testFault=NativeRackHarvestChecks::fault;need(root().command(false),"activate ordinary Rack payload");stage=1;return;}
        if(fired){if(partial!=null&&partial.isCompletedExceptionally())partial.join();return;}
        if(stage==1){need(!root().blocked(),"capture stroke "+root().error());if(NativeGearJournal.busy(root())||root().progress()!=0||root().payload()==null)return;need(!phase().equals("crash"),"crash fixture cannot report ordinary harvest instead of actual fault");need(!root().payload().materialized()&&world.getBlockState(SOURCE).isAir(),"fractional endpoint retains sole captured Rack");need(root().payload().endpoint(root(),0).isEmpty(),"genuine fractional endpoint");need(drops().isEmpty(),"capture removes source without leaking or duplicating internal modules");int count=0;for(var cell:root().payload().cells())if(NativeGearSnapshot.stage(world,cell,false) instanceof NativeRackEntity rack){need(rack.ownedModuleDrops().size()==3,"captured Rack owns all three modules");count++;}need(count==1,"exactly one captured Rack");
            var view=root().payload().view(ROOT,world.registryAccess());var wire=view.write();var projection=view.cells().getFirst().projection();need(projection.getInt("ModuleMask")==7&&projection.getInt("ModuleKinds")==37&&projection.getBoolean("RackPublic"),"filled captured Rack has typed visible module projection");need(!wire.toString().contains("RackHarvestMarker")&&!wire.toString().contains("Items")&&!wire.toString().contains("RackAutopilot"),"captured public wire omits module inventory/private state");need(NativeGearPayloadView.read(wire,world.registryAccess()).write().equals(wire),"strict public Rack wire round trip");var forged=wire.copy();forged.getList("Projections",net.minecraft.nbt.Tag.TAG_COMPOUND).getCompound(0).putString("PrivateModule","forbidden");boolean refused=false;try{NativeGearPayloadView.read(forged,world.registryAccess());}catch(IllegalArgumentException expected){refused=true;}need(refused,"nonpublic carried Rack projection fields refused");
            for(boolean creative:new boolean[]{false,true}){actor.setGameMode(creative?GameType.CREATIVE:GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);var receipt=NativeGearHarvestReceipt.prepare(root(),actor,0);need(receipt.drops().size()==3&&receipt.drops().stream().noneMatch(drop->drop.stack().is(NativeRackBindings.BLOCK.asItem())),"creative/wrong-tool receipt retains all modules without shell "+creative);}actor.setGameMode(GameType.SURVIVAL);stage=2;return;}
        if(stage==2){need(!root().blocked(),"durable harvest "+root().error());if(root().payload()!=null&&!NativeGearJournal.busy(root())){actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND_PICKAXE));need(aim(),"actual unoccluded captured-cell ray");need(NativeGearHarvest.dig(actor,new NativeGearHarvestPayload(ROOT,root().identity(),false)),"real Survival dig intent accepted");}if(root().payload()!=null||NativeGearJournal.busy(root()))return;int shell=0,blank=0,autopilot=0;var seen=new HashSet<Integer>();for(var drop:drops()){need(!NativeGearDropEscrow.held(drop),"modules usable only after asynchronous journal retirement");var item=drop.getItem();if(item.is(NativeRackBindings.BLOCK.asItem())){shell+=item.getCount();need(!item.has(DataComponents.BLOCK_ENTITY_DATA),"shell cannot duplicate contained modules");}if(item.is(NativeRackBindings.BLANK)||item.is(NativeRackBindings.AUTOPILOT)){if(item.is(NativeRackBindings.BLANK))blank+=item.getCount();else autopilot+=item.getCount();need(item.getCount()==1&&seen.add(NativeRackData.data(item).getInt("RackHarvestMarker")),"unique original private module data");}}need(shell==1&&blank==2&&autopilot==1&&seen.equals(Set.of(17,18,19)),"exactly one shell and three original modules after captured mining");need(world.getBlockState(SOURCE).isAir(),"no native source duplicate");running=false;NativeGearJournal.testFault=null;NativeGearJournal.testPause=null;System.out.println("[vandorlabs][rack-harvest] "+phase()+" PASS checks="+checks+" realCapture/fractionalRay/SurvivalDig/asyncHARVEST/shell1/blank2/autopilot1/privateData");event.getServer().halt(false);}
    }catch(Throwable failure){fail(failure);}}
    private static void fail(Throwable failure){running=false;NativeGearJournal.testFault=null;NativeGearJournal.testPause=null;failure.printStackTrace();System.out.println("[vandorlabs][rack-harvest] FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
